.sidebar {
  width: 250px;
  /* Sidebar width */
  background-color: #333;
  color: #fff;
  height: 100vh;
  display: flex;
  flex-direction: column;
  position: fixed;
  top: 0;
  left: 0;
  z-index: 1000;
  /* Ensure sidebar is above other elements */
}

.sidebar-header {
  padding: 20px;
  background-color: #444;
  text-align: center;
}

.sidebar-header h2 {
  margin: 0;
  font-size: 1.5em;
}

.sidebar-nav {
  flex: 1;
  /* Take available space */
  overflow-y: auto;
  /* Enable scrolling if necessary */
}

.sidebar-nav ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.sidebar-nav li {
  border-bottom: 1px solid #555;
  /* Divider for items */
}

.nav-link {
  display: flex;
  align-items: center;
  color: #fff;
  text-decoration: none;
  padding: 15px 20px;
}

.nav-link:hover {
  background-color: #555;
  /* Hover effect */
}

