.border-end {
  border-right: 1px solid #ddd;
  /* Subtle border for the sidebar */
  /* background: linear-gradient(270deg,#a76c9f,#546e8b); */
  /* margin-left: 0px; */
}

.design-area {
  position: relative;
  border: 1px solid #ccc;
  /* Border around the design area */
  border-radius: 8px;
  background-color: #fff;
  /* White background for the canvas */
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
  /* Light shadow for depth */
  padding-left: 20px;
  padding-bottom: 20px;
}

.canvas {
  border: 1px solid #eaeaea;
  /* Border around the canvas */
  border-radius: 4px;
  background-color: #f0f0f0;
  /* Light gray background for the canvas */
  /* background: linear-gradient(270deg,#f0f0f0,#007bff); */
}

button {
  transition: background-color 0.2s, transform 0.2s;
  /* align-items: center; */
  /* Smooth button hover effect */
  /* justify-content: center; */
  justify-items: center;
}

/* button:hover {
  background-color: #e2e6ea;
  Light gray on hover
  transform: translateY(-2px);
  Lift effect
} */

.desingbtn {
  font-size: 18px;
  /* Increase font size for buttons */
  color: #007bff;
  /* Bootstrap primary color */
}

.desingbtn:hover {
  color: #0056b3;
  /* Darker shade on hover */
}

.design-templates-list {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  /* Space between template items */
}

.design-template-item {
  width: 100px;
  height: 100px;
  border: 1px solid #ddd;
  border-radius: 4px;
  /* Rounded corners for template items */
  cursor: pointer;
  overflow: hidden;
  /* Hide overflow for image */
  transition: transform 0.2s;
  /* Smooth scale effect */
}

.design-template-item:hover {
  transform: scale(1.05);
  /* Slight scale on hover */
}

.design-template-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  /* Cover to fill the item */
}

.modal-header {
  background-color: #007bff;
  /* Bootstrap primary color for modal header */
  color: #fff;
  /* White text */
}

.modal-footer {
  justify-content: space-between;
  /* Space between buttons in modal footer */
}

/* Add padding to inputs */
input[type="text"],
.form-control {
  padding: 10px;
  /* Add padding for input fields */
}

/* Style for the alert messages */
.alert {
  margin-top: 20px;
  /* Space above alerts */
  border-radius: 5px;
  /* Rounded corners for alerts */
}

.head {
  padding-top: 50px;
  color: #000;
  text-align: center;
  font-family: 'Dancing script';
  font-size: 25px;
