___CSS_LOADER_EXPORT___.push([module.id, `body {
    margin: 0;
    min-height: 100vh;
    display: grid;
    place-content: center;
    overflow: hidden;
    /* background: url('bg.png') no-repeat center center fixed; */
    background-size: cover;
    
}

.head {
    font-size: 20px;
    color: white;
    font-weight: bold;
}

.gallery {
    --s: 180px; /* Image size */
    display: grid;
    transform-style: preserve-3d;
    animation: r 30s linear infinite; /* Slowed down the rotation */
    position: relative;
    margin-top: 50px;
}

@keyframes r {
    0% {
        transform: perspective(450px) rotateX(-90deg) rotate(0deg);
    }
    100% {
        transform: perspective(450px) rotateX(-90deg) rotate(360deg);
    }
}

.gallery > img {
    grid-area: 1/1;
    width: var(--s);
    aspect-ratio: 1;
    object-fit: cover;
    border-radius: 10px 10px 0 0;
    transform: rotate(var(--_a)) translateY(120%) rotateX(90deg) scaleX(-1); /* Flips the image to correct the mirror effect */
}

.gallery > img:nth-child(1) {
    --_a: 0deg;
}

.gallery > img:nth-child(2) {
    --_a: 60deg;
}

.gallery > img:nth-child(3) {
    --_a: 120deg;
}

.gallery > img:nth-child(4) {
    --_a: 180deg;
}

.gallery > img:nth-child(5) {
    --_a: 240deg;
}

.gallery > img:nth-child(6) {
    --_a: 300deg;
}

.gallery::before {
    content: "";
    position: absolute;
    inset: -100%;
    clip-path: polygon(50% 0, calc(50% + .866*50%) 25%, calc(50% + .866*50%) 75%, 50% 100%, calc(50% - .866*50%) 75%, calc(50% - .866*50%) 25%);
    background: #99B2B7;
    transform: translateZ(calc(var(--s)/2)) rotate(90deg);
}

