___CSS_LOADER_EXPORT___.push([module.id, `.cards-container {
    display: flex;
    flex-wrap: wrap;
    gap: 20px;
    padding: 20px;
  }
  
  .card {
    background-color: #f8f9fa;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    padding: 20px;
    text-align: center;
    display: flex;
    flex-direction: column;
    justify-content: center; /* Center content vertically */
    align-items: center; /* Center content horizontally */
    flex: 1 1 calc(33.333% - 20px); /* Three cards in the first row */
    max-width: calc(33.333% - 20px);
    box-sizing: border-box;
    min-height: 200px; /* Increase the height */
  }
  
  .card:nth-child(n+4) {
    flex: 1 1 calc(50% - 20px); /* Two cards in the second row */
    max-width: calc(50% - 20px);
    min-height: 150px; /* Increase the height for smaller cards */
  }
  
  .card h3 {
    margin: 0;
    font-size: 1.25em;
    color: #333;
  }
  
  .card p {
    font-size: 1.5em;
    color: #007bff;
    margin: 10px 0 0;
  }
  .graphs-container {
    display: flex;
    gap: 20px;
    padding: 20px;
  }
  
  .graph {
    flex: 1;
    min-height: 300px;
  }
  
