___CSS_LOADER_EXPORT___.push([module.id, `/* Admin Layout - Flexbox for Sidebar and Content */
.admin-layout {
  display: flex;
  min-height: 100vh;
  background-color: #f4f7fc; /* Light background for the whole layout */
}

/* Sidebar Styling */
.admin-sidebar {
  width: 250px;
  background-color: #2c3e50; /* Dark background for sidebar */
  color: #ecf0f1;
  padding: 20px;
  position: fixed;
  height: 100vh; /* Full height sidebar */
  transition: width 0.3s ease; /* Smooth transition for expanding/shrinking */
}

.admin-sidebar:hover {
  width: 270px; /* Expanding effect on hover */
}

/* Content Area Styling */
.admin-content {
  margin-left: 250px; /* Matches sidebar width */
  padding: 30px;
  flex: 1;
  background-color: #fff;
  box-shadow: 0px 4px 12px rgba(0, 0, 0, 0.1); /* Slight shadow for content separation */
  transition: margin-left 0.3s ease;
  min-height: 100vh;
}

/* Responsive Sidebar (Mobile) */
@media (max-width: 768px) {
  .admin-sidebar {
      width: 60px;
  }

  .admin-content {
      margin-left: 60px;
  }
}

/* Smooth transitions and hover effects for content links */
.admin-sidebar a {
  display: block;
  color: #ecf0f1;
  padding: 10px 15px;
  text-decoration: none;
  font-size: 16px;
  border-radius: 5px;
  transition: background-color 0.3s, padding-left 0.3s;
}

.admin-sidebar a:hover {
  background-color: #34495e; /* Hover effect */
  padding-left: 25px; /* Slide effect */
}

/* Headings and text inside the content */
.admin-content h1, .admin-content h2, .admin-content h3 {
  color: #34495e;
  margin-bottom: 20px;
  font-weight: 600;
}

.admin-content p {
  color: #7f8c8d;
  line-height: 1.8;
}

/* Button Styling */
button {
  background-color: #1c0730;
  color: #fff;
  padding: 10px 20px;
  border: none;
  border-radius: 5px;
  font-size: 16px;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

button:hover {
  background-color: #2980b9;
}

/* Optional box shadow for an appealing layout */
.admin-layout {
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}
