/* Ensure cards are responsive and centered */
.container {
    max-width: 1200px;
    margin: 0 auto;
}

/* Card styling */
.card {
    border: none;
    border-radius: 10px;
    box-shadow: 5px 4px 12px rgb(132, 104, 104);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    overflow: hidden;
    background: linear-gradient(190deg, #8fb9a9, #475253);
}

/* Hover effect for the card */
.card:hover {
    transform: translateY(-10px);
    box-shadow: 0px 10px 20px rgb(87, 201, 201);
}

/* Ensure the card image fits well */
.card-img-top {
    border-top-left-radius: 10px;
    border-top-right-radius: 10px;
    height: 250px;
    object-fit: cover;
    transition: transform 0.3s ease;
}

/* Image zoom effect on hover */
.card:hover .card-img-top {
    transform: scale(1.05);
}

/* Card body styling */
.card-body {
    text-align: center;
    padding: 20px;
    background: linear-gradient(90deg, #80b6ba, #d2b1ce);
    border-bottom-left-radius: 10px;
    border-bottom-right-radius: 10px;
}

/* Title and text styling */
.card-title {
    font-size: 1.2rem;
    font-weight: bold;
    color: #333;
    margin-bottom: 10px;
}

.card-text {
    font-size: 1rem;
    color: #555;
    margin-bottom: 15px;
}

/* Price styling */
.card-text strong {
    color: #ff6347;
    font-size: 1.1rem;
}

/* Button styling */
.designnow {
    padding: 10px 20px;
    border-radius: 3%;
    font-size: 0.9rem;
    transition: background-color 0.3s ease;
    background: linear-gradient(90deg, #39b8bf, #9a4495);
    width: 180px;
}

.designnow:hover {
    background: linear-gradient(90deg, #1e6063, #793574);
}
.template {
    height: 800px;
    width: 1300px;
}

.templatetext h2 {
    font-weight: 800;
    font-size: 36px;
    line-height: 40px;
    color: white;
}

.templatetext {
    font-size: 20px;
    text-align: center;
}
