    padding: 10px;
}
.footer {
    background: rgba(8, 12, 24, 0.9); /* Matching the dark theme with transparency */
    backdrop-filter: blur(8px);
    color: white;
    padding: 40px 20px;
    position: relative;
    bottom: 0;
    width: 100%;
    box-shadow: 0 -4px 10px rgba(0, 0, 0, 0.3);
}

.footer-content {
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 20px;
}

.footer-section {
    flex: 1;
    min-width: 200px;
}

.footer-section h2 {
    font-size: 1.5rem;
    margin-bottom: 15px;
    color: rgb(85, 212, 193); /* Accent color */
}

.footer-section p,
.footer-section a {
    font-size: 1rem;
    color: #ffffff;
    text-decoration: none;
    margin-bottom: 10px;
    display: block;
}

.footer-section a:hover {
    color: rgb(62, 175, 158); /* Accent hover effect */
}

.footer-bottom {
    text-align: center;
    padding-top: 20px;
    border-top: 1px solid rgba(255, 255, 255, 0.2);
    font-size: 0.9rem;
}
